def txt(s,x,top,width,style='body'):
 p=Paragraph(s,styles[style]);_,height=p.wrap(width,1500);p.drawOn(C,x,top-height);text_boxes.append({'page':page_no,'x':x,'y':top-height,'w':width,'h':height});return height

def page(title,sub,tag):
 global page_no
 page_no+=1;C.setFillColor(CREAM);C.rect(0,0,W,H,fill=1,stroke=0);C.setFillColor(INK);C.rect(0,H-10,W,10,fill=1,stroke=0)
 C.setFont('Bold',10);C.drawString(M,H-36,'СПИМ С ХАСКИ / ЛЕЖАНДР');C.setFont('Reg',9);C.drawRightString(W-M,H-36,'E01 · R08/R09 · 06.10.2026 · '+tag)
 C.setFont('Bold',25);C.drawString(M,H-78,title);txt(sub,M,H-96,W-2*M)
 C.setStrokeColor(colors.HexColor('#d6cabc'));C.line(M,39,W-M,39);C.setFont('Reg',8);C.setFillColor(MUT)
 C.drawString(M,24,'Заданные положения CAD-сетки, не испытание выхода. Ткань и наполнитель не симулированы под нагрузкой.')
 C.setFont('Bold',11);C.drawRightString(W-M,22,f'{page_no:02}');C.bookmarkPage('p'+str(page_no));C.addOutlineEntry(title,'p'+str(page_no),0)

def pic(name,x=M,y=172,w=W-2*M,h=520,common=True):
 im=Image.open(HERE/'renders'/name).convert('RGB')
 if common:im=im.crop(COMMON)
 else:
  a=np.array(im);ys,xs=np.where(a.min(2)<178)
  if len(xs):im=im.crop((max(0,int(xs.min())-35),max(0,int(ys.min())-35),min(im.width,int(xs.max())+35),min(im.height,int(ys.max())+35)))
 ratio=min(w/im.width,h/im.height);dw=im.width*ratio;dh=im.height*ratio;bio=BytesIO();im.save(bio,format='JPEG',quality=94,subsampling=0);bio.seek(0)
 C.drawImage(ImageReader(bio),x+(w-dw)/2,y+(h-dh)/2,dw,dh)

def cards(items,y=57,h=98):
 gap=14;ww=(W-2*M-gap*(len(items)-1))/len(items)
 for i,(title,body) in enumerate(items):
  x=M+i*(ww+gap);C.setFillColor(PALE);C.roundRect(x,y,ww,h,7,fill=1,stroke=0);C.setFillColor(INK);C.setFont('Bold',12);C.drawString(x+14,y+h-23,title);txt(body,x+14,y+h-35,ww-28,'small')

def twin(a,b,labels):
 ww=(W-2*M-20)/2
 pic(a,M,218,ww,472,False);pic(b,M+ww+20,218,ww,472,False)
 txt(labels[0],M,207,ww);txt(labels[1],M+ww+20,207,ww)

def end():C.showPage()

